# OpenAI 兼容：function 型
openai_tools = [{
    "type": "function",
    "function": {
        "name": "get_weather",
        "description": "查询某城市当前天气，需要城市名",
        "parameters": {
            "type": "object",
            "properties": {"city": {"type": "string"}},
            "required": ["city"],
        },
    },
}]

# Anthropic：input_schema 型（字段名不同，语义一致）
anthropic_tools = [{
    "name": "get_weather",
    "description": "查询某城市当前天气，需要城市名",
    "input_schema": {
        "type": "object",
        "properties": {"city": {"type": "string"}},
        "required": ["city"],
    },
}]

# Anthropic 版：tool_result 里用 is_error 标记失败
for block in resp.content:
    if block.type == "tool_use":
        try:
            result = run_tool(block.name, block.input)
            content = [{"type": "tool_result", "tool_use_id": block.id,
                        "content": str(result)}]
        except Exception as e:
            content = [{"type": "tool_result", "tool_use_id": block.id,
                        "content": f"调用失败: {e}", "is_error": True}]
        messages.append({"role": "user", "content": content})
